    state.ball = { x: 94, y: 124, r: BALL_R, vx: 60, vy: 6 };

    jouer(t, state);

    assert.ok(state.ball.vx < 0, `vx devait s'inverser une seule fois : ${state.ball.vx}`);
    assert.ok(state.ball.vy > 0, `vy devait rester positif : ${state.ball.vy}`);
